class LegacyShimFinder(MetaPathFinder):
    """Intercepts legacy imports and maps them to canonical monika modules."""

    def __init__(self, mapping: dict[str, str]) -> None:
        self.mapping = mapping
        self.packages: set[str] = set()
        for k in mapping.keys():
            parts = k.split(".")
            for i in range(1, len(parts)):
                self.packages.add(".".join(parts[:i]))

    def find_spec(
        self,
        fullname: str,
        path: Sequence[str] | None,
        target: types.ModuleType | None = None,
    ) -> ModuleSpec | None:
        if fullname in self.mapping:
            canonical_name = self.mapping[fullname]
            try:
                spec = importlib.util.find_spec(canonical_name)
            except Exception:
                spec = None
            if spec:
                return ModuleSpec(
                    fullname,
                    LegacyLoader(canonical_name),
                    is_package=spec.submodule_search_locations is not None,
                )
        if fullname in self.packages:
            return ModuleSpec(fullname, PackageLoader(fullname), is_package=True)
        return None


class PackageLoader(Loader):
    """Creates synthetic package modules for intermediate legacy namespace nodes."""

    def __init__(self, name: str) -> None:
        self.name = name

    def create_module(self, spec: ModuleSpec) -> types.ModuleType:
        mod = types.ModuleType(spec.name)
        mod.__path__ = []
        mod.__package__ = spec.name
        return mod

    def exec_module(self, module: types.ModuleType) -> None:
        pass


class LegacyLoader(Loader):
    """Loads and aliases the canonical monika module into sys.modules under legacy name."""

    def __init__(self, canonical_name: str) -> None:
        self.canonical_name = canonical_name

    def create_module(self, spec: ModuleSpec) -> types.ModuleType:
        mod = importlib.import_module(self.canonical_name)
        sys.modules[spec.name] = mod
        if "." in spec.name:
            parent_name, attr = spec.name.rsplit(".", 1)
            if parent_name in sys.modules:
                setattr(sys.modules[parent_name], attr, mod)
        return mod

    def exec_module(self, module: types.ModuleType) -> None:
        pass


_installed = False

def install_legacy_compat() -> None:
    """Install the LegacyShimFinder into sys.meta_path if not already present."""
    global _installed
    if _installed:
        return
    for finder in sys.meta_path:
        if isinstance(finder, LegacyShimFinder):
            _installed = True
            return
    sys.meta_path.insert(0, LegacyShimFinder(MODULE_MAPPING))
    _installed = True

# Install automatically on import
install_legacy_compat()
